  ('b134febe-86c9-5a54-afea-18bc38baf9f4', 'Keerai mutton curry', 'tamil', 'dinner', 'nonveg', 2, 60, '["Pressure-cook mutton with turmeric and salt.","Cook onion, ginger-garlic, tomato and powders.","Add mutton and chopped spinach; simmer 10 min."]'::jsonb, 'Greens and meat together — iron, protein and flavour.', 'A Sunday-night classic, greener.', 'built-in library (written by Claude)', 'library-2026-11-18', null, 'computed', 269, 31.2, 10.2, 15.4, 1, false, '{}', '2026-01-01T00:00:00Z'),
  ('d185f5b4-060c-5f7e-a79d-e5c94f05ca82', 'Baked rohu fish kebabs with mint yogurt', 'mixed', 'dinner', 'nonveg', 2, 35, '["Steam the fish, flake it and remove bones.","Mix with besan, onion, ginger-garlic, chilli, garam masala and coriander; shape kebabs.","Brush with oil and bake at 200 °C for 15 min.","Blend yogurt with mint for the dip."]'::jsonb, 'Besan binds the kebabs and adds a little protein.', 'Kebab night, oven-baked.', 'built-in library (written by Claude)', 'library-2026-11-18', null, 'computed', 386, 38, 17.4, 18.2, 1, false, '{}', '2026-01-01T00:00:00Z'),
  ('e17860fe-3c5c-5459-aee7-d51280ff6a36', 'Baked chana dal vada with curd dip', 'tamil', 'dinner', 'veg', 2, 40, '["Soak chana dal 2 hours; grind coarsely with ginger, chilli and fennel.","Mix in onion and curry leaves; shape patties.","Brush with oil and bake at 200 °C for 20 min, turning once. Serve with cucumber-yogurt dip."]'::jsonb, 'All the masala vada flavour without the deep fryer.', 'Tea-time favourite as a light dinner.', 'built-in library (written by Claude)', 'library-2026-11-18', null, 'computed', 416, 19.8, 13, 58, 0.996, false, '{"curry leaves"}', '2026-01-01T00:00:00Z'),
  ('fd3ecf5f-048e-581c-a632-f2d783e58e1c', 'Quinoa egg fried rice', 'mixed', 'dinner', 'egg', 2, 25, '["Cook quinoa and cool it.","Scramble eggs and whites; set aside.","Stir-fry garlic and vegetables on high heat; add quinoa, soy sauce, pepper and the eggs."]'::jsonb, 'Quinoa stays fluffy and adds protein over rice.', 'Indo-Chinese night, upgraded.', 'built-in library (written by Claude)', 'library-2026-11-18', null, 'computed', 419, 23.9, 17, 43.2, 1, false, '{}', '2026-01-01T00:00:00Z'),
  ('50d8f961-ee39-56de-a206-6984f0baf2d7', 'Chilli paneer, Chennai street style', 'mixed', 'dinner', 'veg', 2, 25, '["Toss paneer in rice flour and pan-sear till golden.","Stir-fry garlic, ginger, chilli, onion and capsicum on high heat.","Add soy sauce, vinegar and paneer; toss. Finish with spring onion."]'::jsonb, 'Pan-seared, not deep-fried — the street flavour stays.', 'Chennai''s favourite Indo-Chinese dish.', 'built-in library (written by Claude)', 'library-2026-11-18', null, 'computed', 495, 22.4, 25.7, 43, 1, false, '{}', '2026-01-01T00:00:00Z'),
  ('dc39e333-3ee4-5577-a134-45a98694c2f0', 'Chicken shawarma chapati roll with garlic hung curd', 'mixed', 'dinner', 'nonveg', 2, 30, '["Marinate chicken in half the hung curd with spices and lemon; sear and slice.","Mix the remaining hung curd with grated garlic and salt for the sauce.","Roll chicken, lettuce, onion and tomato in chapatis with the sauce."]'::jsonb, 'Hung curd ''toum'' is lighter than mayo and full of protein.', 'Food-court flavour, home-made.', 'built-in library (written by Claude)', 'library-2026-11-18', null, 'computed', 456, 46.5, 9.7, 47.3, 1, false, '{}', '2026-01-01T00:00:00Z'),
  ('247d7ebc-365a-59f4-a97c-df7fbb0dadcb', 'Sprouts and egg chaat salad', 'mixed', 'dinner', 'egg', 2, 15, '["Steam sprouts 3 min. Boil and chop the eggs.","Toss with onion, tomato, cucumber, chilli, coriander and lemon.","Top with roasted gram for crunch."]'::jsonb, 'Chaat flavours, zero frying.', 'A tangy 15-minute dinner.', 'built-in library (written by Claude)', 'library-2026-11-18', null, 'computed', 260, 17, 14.4, 18, 1, true, '{}', '2026-01-01T00:00:00Z'),
  ('c00324fb-e046-5aa4-a266-59f4d5e0dc59', 'Baked tuna cutlets with kachumber', 'mixed', 'dinner', 'nonveg', 2, 35, '["Steam and flake the tuna; mash with boiled potato, onion, chilli, ginger, garam masala and coriander.","Shape cutlets, dip in beaten egg and bake at 200 °C for 18 min.","Toss cucumber and tomato with lemon and salt."]'::jsonb, 'Kerala-style cutlets, oven-baked.', 'Tea-shop favourite, dinner-ready.', 'built-in library (written by Claude)', 'library-2026-11-18', null, 'computed', 324, 43, 8, 18.9, 1, false, '{}', '2026-01-01T00:00:00Z'),
  ('01128320-6432-5042-a34f-39129f1722f5', 'Mushroom and egg pepper masala with chapati', 'mixed', 'dinner', 'egg', 2, 25, '["Make chapatis.","Sauté onion, garlic and curry leaves; add mushrooms and cook till browned.","Add tomato and pepper; scramble in the eggs."]'::jsonb, 'Mushrooms add a meaty bite with very few calories.', 'Quick, peppery and satisfying.', 'built-in library (written by Claude)', 'library-2026-11-18', null, 'computed', 397, 20.5, 15.1, 49.5, 0.997, false, '{"curry leaves"}', '2026-01-01T00:00:00Z')
